        rc = bicycle_demo_scene_step(strcmp(arg, "next") == 0 ? 1 : -1);
        if (rc == 0) {
            bicycle_ui_ctl_demo_scene_toast();
        } else {
            lv_pm_bottom_show("演示场景启动失败", 0);
        }
        return;
